


/** Immutable posted financial movement with signed amount, per-card sequence, merchant sequence and balance snapshots. Corrections create new transactions. */ export type GiftCardTransactionInput = { "amount_money"?: never; "balance_after_money"?: never; "balance_before_money"?: never; /** Caller-owned identifier for this resource in an external system. maxLength: 255. */ "external_reference_id"?: never; "gift_card_id"?: never; "gift_card_transaction_id"?: never; "idempotency_key"?: never; /** Use an exact numeric string, not a floating-point number. Format: int64. */ "merchant_sequence"?: never; "order_id"?: never; /** RFC3339 timestamp. Format: date-time. */ "posted_at"?: never; "reason"?: never; /** Use an exact numeric string, not a floating-point number. Format: int64. */ "sequence"?: never; "source_id"?: never; "source_type"?: never; "transaction_type"?: never; };
